import{_ as t,o as r,c as a,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"The Agentic Development Framework","description":"Component of the Agentic Development Framework documentation.","frontmatter":{"type":"Agentic Development Framework","title":"The Agentic Development Framework","description":"Component of the Agentic Development Framework documentation.","tags":["framework","internal"],"isInternal":true},"headers":[],"relativePath":"framework/index.md","filePath":"framework/index.md"}'),n={name:"framework/index.md"};function o(l,e,s,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="the-agentic-development-framework" tabindex="-1">The Agentic Development Framework <a class="header-anchor" href="#the-agentic-development-framework" aria-label="Permalink to &quot;The Agentic Development Framework&quot;">​</a></h1><p><strong>A Practitioner&#39;s Guide to Structuring AI-Native Software Projects</strong></p><hr><p><em>Version 1.0 — July 2026</em><em>Distilled from the Sanjeev AI production codebase</em></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Modern AI coding assistants are powerful, but without deliberate structural guardrails, they hallucinate, duplicate work, violate security boundaries, and accumulate context debt that degrades output quality over time. This paper presents the <strong>Agentic Development Framework (ADF)</strong> — a set of architectural patterns, file conventions, and operational workflows that transform an AI coding assistant from a reactive autocomplete tool into a disciplined, self-improving development partner.</p><p>The framework was developed and battle-tested during the construction of a production SaaS application (React, Firebase, Vertex AI) and is designed to be adopted incrementally by any team using AI-assisted development.</p><hr><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ol><li><a href="#1-introduction">Introduction: The Problem with Unstructured AI Development</a></li><li><a href="#2-the-seven-pillars">The Seven Pillars of the Agentic Development Framework</a><ul><li><a href="#pillar-1-the-agent-rules-file">Pillar 1: The Agent Rules File (Central Control Plane)</a></li><li><a href="#pillar-2-the-skills-registry">Pillar 2: The Skills Registry (Domain Knowledge)</a></li><li><a href="#pillar-3-swarm-architecture">Pillar 3: Swarm Architecture (Multi-Role Execution)</a></li><li><a href="#pillar-4-agentic-tdd">Pillar 4: Agentic Test-Driven Development</a></li><li><a href="#pillar-5-self-updating-memory">Pillar 5: Self-Updating Memory (Knowledge Harvesting)</a></li><li><a href="#pillar-6-context-routing">Pillar 6: Context Routing (Token Efficiency)</a></li><li><a href="#pillar-7-closed-loop-cicd">Pillar 7: Closed-Loop CI/CD (Post-Deployment Monitoring)</a></li></ul></li><li><a href="#3-reference-implementation">Reference Implementation</a></li><li><a href="#4-the-maturity-model">The Maturity Model</a></li><li><a href="#5-operational-lessons-learned">Operational Lessons Learned</a></li><li><a href="#6-adoption-guide">Adoption Guide</a></li></ol><hr><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><h3 id="the-problem-with-unstructured-ai-development" tabindex="-1">The Problem with Unstructured AI Development <a class="header-anchor" href="#the-problem-with-unstructured-ai-development" aria-label="Permalink to &quot;The Problem with Unstructured AI Development&quot;">​</a></h3><p>When an AI coding assistant operates without structural constraints, five failure modes reliably emerge:</p><table tabindex="0"><thead><tr><th>Failure Mode</th><th>Symptom</th><th>Root Cause</th></tr></thead><tbody><tr><td><strong>Context Collapse</strong></td><td>The agent reads irrelevant files, consuming its context window with noise</td><td>No routing rules define which files are relevant to which task</td></tr><tr><td><strong>Knowledge Amnesia</strong></td><td>The agent re-discovers solutions to problems it already solved in a prior session</td><td>No mechanism to persist and retrieve session-local learnings</td></tr><tr><td><strong>Hallucination Drift</strong></td><td>The agent generates plausible but incorrect code that silently passes review</td><td>No adversarial testing phase; the builder reviews its own work</td></tr><tr><td><strong>Security Bypass</strong></td><td>The agent writes code that circumvents access control rules</td><td>No mandatory security audit gate in the development workflow</td></tr><tr><td><strong>Stale Documentation</strong></td><td>The agent reads outdated specs and implements features that already exist</td><td>No process to keep planning documents in sync with reality</td></tr></tbody></table><p>The Agentic Development Framework addresses each of these failure modes through deliberate architectural choices.</p><h3 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h3><p>The framework rests on three principles:</p><ol><li><strong>Agents are junior developers, not architects.</strong> They need clear instructions, bounded scope, and mandatory review gates — not unrestricted autonomy.</li><li><strong>Documentation is infrastructure, not overhead.</strong> Every document in the repository is a potential instruction set for an AI agent. Stale docs are broken infrastructure.</li><li><strong>Token efficiency is a first-class concern.</strong> An agent&#39;s context window is a finite resource. Wasting it on irrelevant files directly degrades output quality.</li></ol><hr><h2 id="_2-the-seven-pillars" tabindex="-1">2. The Seven Pillars <a class="header-anchor" href="#_2-the-seven-pillars" aria-label="Permalink to &quot;2. The Seven Pillars&quot;">​</a></h2>',22)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
